"use client"

import { useQuery } from "@tanstack/react-query"
import { StatCard } from "../stat-card"
import { CompanyCard } from "../company-card"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { CheckCircle2, ArrowUpRight, TrendingUp, Calendar, Building2 } from "lucide-react"
import { 
  fetchGlobalIncomeStatement, 
  fetchGlobalBalanceSheet, 
  fetchCompanyComparison,
  fetchRecurringTransactions,
  fetchCompanies
} from "@/lib/api"
import { useState } from "react"

interface DashboardOverviewProps {
  onNavigate: (tab: string) => void
}

export function DashboardOverview({ onNavigate }: DashboardOverviewProps) {
  const currentYear = new Date().getFullYear()
  const today = new Date().toISOString().split('T')[0]
  
  const [selectedYear, setSelectedYear] = useState(currentYear)

  // Fetch global financial data
  const { data: incomeStatement, isLoading: incomeLoading } = useQuery({
    queryKey: ["global-income-statement", selectedYear],
    queryFn: () => fetchGlobalIncomeStatement(selectedYear),
  })

  const { data: balanceSheet, isLoading: balanceLoading } = useQuery({
    queryKey: ["global-balance-sheet", today],
    queryFn: () => fetchGlobalBalanceSheet(today),
  })

  const { data: companyComparison, isLoading: comparisonLoading } = useQuery({
    queryKey: ["company-comparison", selectedYear],
    queryFn: () => fetchCompanyComparison(selectedYear),
  })

  const { data: recurringTransactions, isLoading: recurringLoading } = useQuery({
    queryKey: ["recurring-transactions"],
    queryFn: fetchRecurringTransactions,
  })


  const isLoading = incomeLoading || balanceLoading || comparisonLoading || recurringLoading 

  if (isLoading) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        Loading dashboard data...
      </div>
    )
  }

  // Calculate metrics from the data
  const totalRevenue = incomeStatement?.summary?.totalRevenue || 0
  const totalExpenses = incomeStatement?.summary?.totalOperatingExpenses || 0
  const netIncome = incomeStatement?.summary?.totalNetProfit || 0
  const totalAssets = balanceSheet?.summary?.totalAssets || 0
  const totalLiabilities = balanceSheet?.summary?.totalLiabilities || 0
  const totalEquity = balanceSheet?.summary?.totalEquity || 0

  return (
    <div className="space-y-6">
      {/* Year Selector */}
      <div className="flex items-center justify-between">
        <Alert className="flex-1 bg-emerald-50 dark:bg-emerald-950/20 border-emerald-200 dark:border-emerald-800">
          <CheckCircle2 className="h-4 w-4 text-emerald-600" />
          <AlertDescription className="text-emerald-700 dark:text-emerald-400">
            <strong>Global Financial Overview</strong> — Viewing data for {selectedYear}
          </AlertDescription>
        </Alert>
        
        <div className="flex items-center gap-2 ml-4">
          <Calendar className="h-4 w-4 text-muted-foreground" />
          <select
            value={selectedYear}
            onChange={(e) => setSelectedYear(Number(e.target.value))}
            className="border rounded-md px-3 py-1.5 text-xs bg-background"
          >
            {[currentYear - 2, currentYear - 1, currentYear, currentYear + 1].map(year => (
              <option key={year} value={year}>{year}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Financial Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          label="Total Revenue"
          value={`RWF ${totalRevenue.toLocaleString()}`}
          change={`Year ${selectedYear}`}
          changeType="neutral"
          variant="revenue"
        />
        <StatCard
          label="Total Expenses"
          value={`RWF ${totalExpenses.toLocaleString()}`}
          change={`Year ${selectedYear}`}
          changeType="neutral"
          variant="expense"
        />
        <StatCard
          label="Net Income"
          value={`RWF ${netIncome.toLocaleString()}`}
          change={netIncome >= 0 ? "Profit" : "Loss"}
          changeType={netIncome >= 0 ? "positive" : "negative"}
          variant="profit"
        />
        <StatCard
          label="Total Assets"
          value={`RWF ${totalAssets.toLocaleString()}`}
          change={`As of ${new Date(today).toLocaleDateString()}`}
          changeType="neutral"
          variant="cash"
        />
      </div>

   
      {/* Company Comparison */}
      <Card className="shadow-xl border-border/40">
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-sm font-serif">Company Performance Comparison</CardTitle>
            <p className="text-xs text-muted-foreground mt-1">
              Year {companyComparison?.summary?.year || selectedYear} • {companyComparison?.summary?.totalCompanies || 0} companies
            </p>
          </div>
          <Button variant="outline" onClick={() => onNavigate("companies")}>
            View Details
            <ArrowUpRight className="h-4 w-4 ml-2" />
          </Button>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Company</TableHead>
                  <TableHead className="text-right">Revenue</TableHead>
                  <TableHead className="text-right">Expenses</TableHead>
                  <TableHead className="text-right">Net Profit</TableHead>
                  <TableHead className="text-right">Margin</TableHead>
                  <TableHead className="text-right">Assets</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {companyComparison?.summary?.allCompanies?.map((company: any) => {
                  const margin = company.profitMargin || "0"
                  
                  return (
                    <TableRow key={company.companyId} className="hover:bg-muted/50">
                      <TableCell className="font-medium">
                        <div className="flex items-center gap-2">
                          <Building2 className="h-4 w-4 text-muted-foreground" />
                          {company.companyName}
                        </div>
                      </TableCell>
                      <TableCell className="text-right font-serif text-emerald-600 dark:text-emerald-400">
                        RWF {company.revenue.toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right font-serif text-red-600 dark:text-red-400">
                        RWF {company.expenses.toLocaleString()}
                      </TableCell>
                      <TableCell className={`text-right font-serif font-semibold ${
                        company.netProfit >= 0 
                          ? "text-emerald-600 dark:text-emerald-400" 
                          : "text-red-600 dark:text-red-400"
                      }`}>
                        RWF {company.netProfit.toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right">
                        <Badge variant={Number(margin) >= 0 ? "default" : "destructive"}>
                          {margin}%
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right font-serif">
                        RWF {company.assets.toLocaleString()}
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </div>

          {/* Top Performers Section */}
          {companyComparison?.summary?.topPerformers && (
            <div className="mt-6 pt-6 border-t grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="p-4 bg-emerald-50 dark:bg-emerald-950/20 rounded-lg">
                <h4 className="text-xs font-semibold text-emerald-700 dark:text-emerald-400 mb-2">
                  Top by Revenue
                </h4>
                {companyComparison.summary.topPerformers.byRevenue.slice(0, 1).map((company: any) => (
                  <div key={company.companyId}>
                    <p className="font-medium">{company.companyName}</p>
                    <p className="text-sm font-serif font-bold text-emerald-600">
                      RWF {company.revenue.toLocaleString()}
                    </p>
                  </div>
                ))}
              </div>

              <div className="p-4 bg-blue-50 dark:bg-blue-950/20 rounded-lg">
                <h4 className="text-xs font-semibold text-blue-700 dark:text-blue-400 mb-2">
                  Top by Profit
                </h4>
                {companyComparison.summary.topPerformers.byProfit.slice(0, 1).map((company: any) => (
                  <div key={company.companyId}>
                    <p className="font-medium">{company.companyName}</p>
                    <p className="text-sm font-serif font-bold text-blue-600">
                      RWF {company.netProfit.toLocaleString()}
                    </p>
                  </div>
                ))}
              </div>

              <div className="p-4 bg-violet-50 dark:bg-violet-950/20 rounded-lg">
                <h4 className="text-xs font-semibold text-violet-700 dark:text-violet-400 mb-2">
                  Best Margin
                </h4>
                {companyComparison.summary.topPerformers.byProfitMargin.slice(0, 1).map((company: any) => (
                  <div key={company.companyId}>
                    <p className="font-medium">{company.companyName}</p>
                    <p className="text-sm font-serif font-bold text-violet-600">
                      {company.profitMargin}%
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>


      {/* Recurring Transactions */}
      <Card className="shadow-xl border-border/40">
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-sm font-serif">Recurring Transactions</CardTitle>
            <p className="text-xs text-muted-foreground mt-1">
              {recurringTransactions?.transactions?.length || 0} recurring schedules
            </p>
          </div>
          <Button variant="outline" onClick={() => onNavigate("recurring")}>
            Manage All
            <ArrowUpRight className="h-4 w-4 ml-2" />
          </Button>
        </CardHeader>
        <CardContent>
          {recurringTransactions?.transactions && recurringTransactions.transactions.length > 0 ? (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Company</TableHead>
                    <TableHead>Description</TableHead>
                    <TableHead>Frequency</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead className="text-right">Amount</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {recurringTransactions.transactions.slice(0, 5).map((transaction: any) => (
                    <TableRow key={transaction.id} className="hover:bg-muted/50">
                      <TableCell className="font-medium">
                        <div className="flex items-center gap-2">
                          <Building2 className="h-4 w-4 text-muted-foreground" />
                          {transaction.company?.name || 'N/A'}
                        </div>
                      </TableCell>
                      <TableCell>{transaction.description}</TableCell>
                      <TableCell>
                        <Badge variant="outline" className="capitalize">
                          {transaction.recurringFrequency}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground">
                        {transaction.categoryPath || transaction.category?.name || 'N/A'}
                      </TableCell>
                      <TableCell className={`font-serif text-right ${
                        transaction.transactionType === 'debit' 
                          ? 'text-emerald-600 dark:text-emerald-400' 
                          : 'text-red-600 dark:text-red-400'
                      }`}>
                        {transaction.transactionType === 'credit' ? '-' : '+'}
                        RWF {parseFloat(transaction.amount).toLocaleString()}
                      </TableCell>
                      <TableCell>
                        <Badge variant={transaction.status === 'completed' ? "default" : "secondary"}>
                          {transaction.status}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          ) : (
            <div className="text-center py-8 text-muted-foreground">
              No recurring transactions set up yet.
            </div>
          )}
        </CardContent>
      </Card>

     
    </div>
  )
}